mapper.select:
select c.id, c.name, c.room, c.begin_date, c.end_date, c.master_id, c.create_time, c.update_time, e.name as masterName, (case when current_date between c.begin_date and c.end_date then '已开班' when current_date < c.begin_date then '未开班' when current_date > c.end_date then '已结束' else '未知' end) as status from clazz c left join emp e on c.master_id = e.id
c.name like CONCAT('%', #{name}, '%')
and c.begin_date >= #{begin}
and c.end_date <= #{end}
